\label{def:natarajan}
A sequence $(x_1,\dots,x_d)\in X^d$ is \emph{N-shattered} by $\mathcal{H}$ if there are $f_0,f_1\colon X\to Y$ with $f_0(x_i)\neq f_1(x_i)$ for all $i$, such that for every $\epsilon\in\{0,1\}^d$ some $h\in\mathcal{H}$ satisfies $h(x_i)=f_{\epsilon_i}(x_i)$ for all $i$.
The Natarajan dimension $\operatorname{Nat}(\mathcal{H})$ is the supremum of the lengths of N-shattered sequences.

\label{def:td}
A finite set $A\subseteq X$ is a \emph{teaching set} for $h\in\mathcal{H}$ if $h$ is the only element of $\mathcal{H}$ that agrees with $h$ on $A$.
$\operatorname{TD}(h)$ is the least size of a teaching set for $h$ ($\infty$ if there is none), and $\operatorname{TD}(\mathcal{H})=\sup_{h\in\mathcal{H}}\operatorname{TD}(h)$.

\label{lem:closure}
For all $A,B\subseteq\Omega$:
\textup{(a)} $A\subseteq\operatorname{cl}(A)$;
\textup{(b)} if $A\subseteq B$ then $\operatorname{cl}(A)\subseteq\operatorname{cl}(B)$;
\textup{(c)} $G_{(\operatorname{cl}(A))}=G_{(A)}$, and hence $\operatorname{cl}(\operatorname{cl}(A))=\operatorname{cl}(A)$.

\label{thm:dictionary}
Let $G\le\operatorname{Sym}(\Omega)$, let $X\subseteq\Omega$ be nonempty, and let $\mathcal{H}=\mathcal{H}_{G,X}$.
\begin{enumerate}[label=(\alph*)]
\item \emph{(DS dimension $=$ height.)}
  Assume~\eqref{eq:F}.
  A sequence $\mathbf{a}=(a_1,\dots,a_d)$ in $X$ is DS-shattered by $\mathcal{H}$ if and only if its entries are distinct and $\{a_1,\dots,a_d\}$ is independent.
  In that case $\mathcal{H}|_{\mathbf{a}}$ is itself a $d$-dimensional pseudo-cube.
  Hence $\operatorname{DS}(\mathcal{H})=\mathsf{H}_X(G)$, where both sides may be infinite.
\item \emph{(List DS dimension $=$ list height.)}
  Assume~\eqref{eq:F} and let $k\ge1$.
  A sequence $\mathbf{a}=(a_1,\dots,a_d)$ in $X$ with $A=\{a_1,\dots,a_d\}$ is $k$-DS-shattered by $\mathcal{H}$ if and only if its entries are distinct and $|G_{(A\setminus\{a_i\})}\,a_i|\ge k+1$ for every $i$.
  In that case $\mathcal{H}|_{\mathbf{a}}$ is itself a $k$-pseudo-cube.
  Hence $\operatorname{DS}_k(\mathcal{H})=\mathsf{H}^k_X(G)$.
\item \emph{(Littlestone dimension $=$ irredundant length.)}
  $\operatorname{Ldim}(\mathcal{H})=\mathsf{I}_X(G)$.
\item \emph{(Teaching $=$ bases.)}
  A finite $A\subseteq X$ is a teaching set for $h\in\mathcal{H}$ if and only if $A$ is a relative base.
  Consequently all $h\in\mathcal{H}$ have the same teaching sets, $\operatorname{TD}(h)=\mathsf{b}_X(G)$ for every $h\in\mathcal{H}$, and the supremum of the sizes of the inclusion-minimal teaching sets of any $h\in\mathcal{H}$ is $\mathsf{B}_X(G)$.
\end{enumerate}

\label{thm:galois}
Let $L/K$ be a finite Galois extension of a countable field $K$, with group $\Gamma=\operatorname{Gal}(L/K)$ acting on $\Omega=X=L$, and let $\mathcal{H}=\mathcal{H}_{\Gamma,L}$.
Then~\eqref{eq:F} holds, and:
\begin{enumerate}[label=(\roman*)]
\item $\operatorname{cl}(A)=K(A)$ for every $A\subseteq L$: the learning closure is the field generated by the data;
\item if $\Gamma\neq1$, then $\operatorname{TD}(\mathcal{H})=\mathsf{b}_L(\Gamma)=1$;
\item $\operatorname{DS}(\mathcal{H})=\mathsf{H}_L(\Gamma)=\mu(\Gamma)$; more generally, $\mathsf{H}_L(\Delta)=\mu(\Delta)$ for every subgroup $\Delta\le\Gamma$;
\item $\operatorname{Ldim}(\mathcal{H})=\mathsf{I}_L(\Gamma)=\ell(\Gamma)$;
\item for a finite $A\subseteq L$ and $\alpha\in L$, the set of labels of $\alpha$ consistent with a sample on $A$ has exactly $[K(A)(\alpha):K(A)]$ elements;
\item $\operatorname{Nat}(\mathcal{H})\ge\max\{\mu(\Delta) : \Delta\le\Gamma\text{ abelian}\}$, and for a finite abelian group $\Delta$, $\mu(\Delta)=\sum_p d(\Delta_p)$, where $\Delta_p$ is the Sylow $p$-subgroup and $d(\cdot)$ is the minimal number of generators.
\end{enumerate}

\label{cor:galois-values}
In the setting of \cref{thm:galois}:
\begin{enumerate}[label=(\alph*)]
\item if $\Gamma\cong S_n$ with $n\ge2$, then $\operatorname{TD}=1$, $\operatorname{DS}=n-1$, $\operatorname{Ldim}=\lceil3n/2\rceil-b(n)-1$ and $\lfloor n/2\rfloor\le\operatorname{Nat}\le n-1$;
\item if $\Gamma\cong\mathbb{Z}/n$ with $n\ge2$ (for example $\mathbb{F}_{q^n}/\mathbb{F}_q$), then $\operatorname{TD}=1$, $\operatorname{DS}=\operatorname{Nat}=\omega(n)$ and $\operatorname{Ldim}=\omega^{+}(n)$;
\item if $\Gamma\cong(\mathbb{Z}/2)^r$ with $r\ge1$, then $\operatorname{TD}=1$ and $\operatorname{DS}=\operatorname{Nat}=\operatorname{Ldim}=r$.
\end{enumerate}

\label{prop:symmetric}
Let $\Omega$ be finite and nonempty with $|\Omega|=n$, and let $G\le\operatorname{Sym}(\Omega)$.
\begin{enumerate}[label=(\alph*)]
\item For every nonempty $X\subseteq\Omega$, $\operatorname{Nat}(\mathcal{H}_{G,X})\le\lfloor n/2\rfloor$; and $\mathsf{H}(G)\le n-1$.
\item For $G=S_n$ acting on $[n]$ with $n\ge2$: $\mathsf{H}(S_n)=n-1$ and $\operatorname{Nat}(\mathcal{H}_{S_n,[n]})=\lfloor n/2\rfloor$.
\item \emph{(Direct products.)}
  If $G_1\le\operatorname{Sym}(\Omega_1)$ and $G_2\le\operatorname{Sym}(\Omega_2)$ act on disjoint sets and $G=G_1\times G_2$ acts on $\Omega_1\sqcup\Omega_2$ componentwise, then $\mathsf{H}(G)=\mathsf{H}(G_1)+\mathsf{H}(G_2)$ and $\operatorname{Nat}(\mathcal{H}_{G,\Omega_1\sqcup\Omega_2})=\operatorname{Nat}(\mathcal{H}_{G_1,\Omega_1})+\operatorname{Nat}(\mathcal{H}_{G_2,\Omega_2})$.
\item For every $k\ge1$, $G=S_3^k$ acting on $3k$ points has $\mathsf{H}(G)=2k$ and $\operatorname{Nat}(\mathcal{H}_{G,\Omega})=k$.
\end{enumerate}
Hence $\inf\{\operatorname{Nat}(\mathcal{H}_{G,\Omega})/\mathsf{H}(G) : \mathsf{H}(G)\ge1\}\le1/2$, and the ratio $1/2$ is attained at every even height.

\label{lem:tower}
Let $G\le\operatorname{Sym}(\Omega)$, and let $x_1,\dots,x_t\in\Omega$ be distinct and $k_1,\dots,k_t\in G$ satisfy
\textup{(T1)} $k_jx_j\neq x_j$ for every $j$;
\textup{(T2)} $k_jx_i=x_i$ for all $i\neq j$;
\textup{(T3)} $k_j(k_ix_i)=k_ix_i$ for all $i<j$.
Then $(x_1,\dots,x_t)$ is N-shattered by $\mathcal{H}_{G,X}$ for every $X\supseteq\{x_1,\dots,x_t\}$, with $f_0(x_i)=x_i$ and $f_1(x_i)=k_ix_i$.

\label{prop:square}
Let $G\le\operatorname{Sym}(\Omega)$, let $x\neq y$ be points of $\Omega$, and let $P=G_x$ and $Q=G_y$.
Then $(x,y)$ is N-shattered by $\mathcal{H}_{G,\Omega}$ if and only if $PQ\cap QP\supsetneq P\cup Q$.
Consequently:
\begin{enumerate}[label=(\alph*)]
\item if $h\in G_v$ moves $u$ and $G_{(\{u,hu\})}\not\subseteq G_v$, then $(u,v)$ is N-shattered;
\item if $G$ is finite, $\{x,y\}$ is independent and $PQ=QP$, then $(x,y)$ is N-shattered;
\item if some independent triple $\{a,b,c\}$ has $b\in G_c\,a$, then $\operatorname{Nat}(\mathcal{H}_{G,\Omega})\ge2$; in particular, every $2$-transitive group of height at least $3$ has Natarajan dimension at least $2$.
\end{enumerate}

\label{thm:solvable}
In the setting of \cref{thm:cosetcube}:
\begin{enumerate}[label=(\alph*)]
\item if $\Gamma$ is solvable, then $\operatorname{Nat}(\mathcal{H})=\operatorname{DS}(\mathcal{H})=\mu(\Gamma)$;
\item if $\Gamma\cong A_5$, then $\operatorname{Nat}(\mathcal{H})=2<3=\operatorname{DS}(\mathcal{H})$; if $\Gamma\cong S_5$, then $\operatorname{Nat}(\mathcal{H})=3<4=\operatorname{DS}(\mathcal{H})$;
\item if $\Gamma\cong S_n$ with $n\ge1$, then $\lfloor 3n/4\rfloor\le\operatorname{Nat}(\mathcal{H})\le n-1=\operatorname{DS}(\mathcal{H})$;
\item if $X_0\subseteq L$ is finite and every subgroup of $\Gamma$ is the stabilizer of a point of $X_0$, then $\mathcal{H}_{\Gamma,X_0}$ has finitely many labels, $\operatorname{DS}(\mathcal{H}_{\Gamma,X_0})=\mu(\Gamma)$ and $\operatorname{Nat}(\mathcal{H}_{\Gamma,X_0})=N(\Gamma)$, so (a)--(c) hold verbatim for $\mathcal{H}_{\Gamma,X_0}$.
\end{enumerate}

\label{thm:abelruffini}
\begin{enumerate}[label=(\alph*)]
\item Let $n\ge5$. There are no subgroups $V_1,\dots,V_{n-1}\le S_n$ and elements $k_i\in S_n\setminus V_i$ such that $\bigcap_{i}k_i^{\varepsilon_i}V_i\neq\emptyset$ for every $\varepsilon\in\{0,1\}^{n-1}$ with at most two coordinates equal to~$1$. In particular $N(S_n)\le n-2$.
\item $N(S_n)=n-2$ for $5\le n\le8$.
\item Let $L/K$ be a finite Galois extension of a countable field $K$ with group $\Gamma\cong S_n$, and $\mathcal{H}=\mathcal{H}_{\Gamma,L}$. Then $\operatorname{Nat}(\mathcal{H})=\operatorname{DS}(\mathcal{H})$ if and only if $n\le4$; for $n\ge5$, $\operatorname{Nat}(\mathcal{H})\le n-2<n-1=\operatorname{DS}(\mathcal{H})$. The same holds for $\mathcal{H}_{\Gamma,X_0}$, with $X_0$ as in \cref{thm:solvable}(d).
\end{enumerate}

\label{prop:psl28}
The simple group $\mathrm{PSL}(2,8)$ has $N=\mu=3$.
Consequently, for every finite Galois extension $L/K$ of a countable field with group $\Gamma\cong\mathrm{PSL}(2,8)$, the class $\mathcal{H}_{\Gamma,L}$ has $\operatorname{Nat}=\operatorname{DS}=3$.

\label{prop:pgal}
Let $\Gamma=\mathrm{P\Gamma L}(2,8)=\mathrm{PSL}(2,8)\rtimes\langle\varphi\rangle$, of order $1512$, where $\varphi$ is induced by $x\mapsto x^2$ on $\mathbb F_8$.
Then $N(\Gamma)\ge4$, whereas every chief series of every subgroup of $\Gamma$ has at most $3$ complemented factors; the last statement is computer-assisted.

\label{fact:conjugates}
Let $L/K$ be a finite Galois extension with group $\Gamma$, let $\alpha\in L$, and let $f$ be the minimal polynomial of $\alpha$ over $K$.
Then the orbit $\Gamma\alpha$ is the set of roots of $f$, $f$ is separable, $|\Gamma\alpha|=[K(\alpha):K]$, and $\Gamma_\alpha=\operatorname{Gal}(L/K(\alpha))$.

\label{ext:artin}
Let $G$ be a finite group of automorphisms of a field $E$.
Then $E/E^G$ is a finite Galois extension of degree $|G|$, with Galois group $G$.

\label{ext:radicals}
Let $F$ be a field of characteristic zero.
A polynomial $f\in F[X]$ is solvable in radicals if and only if its Galois group is solvable.

\label{ext:whiston}
Let $n\ge2$.
Every independent subset of $S_n$ has at most $n-1$ elements, and every independent subset of $S_n$ with $n-1$ elements generates $S_n$.

\label{ext:lucchini}
Let $G$ be a finite solvable group.
The largest size of a minimal generating set of $G$ equals the number of complemented factors in any chief series of $G$.

\label{ext:pgl}
For every prime power $q$, the group $\mathrm{PGL}(2,q)$ acts $3$-transitively on the $q+1$ points of the projective line over $\mathbb F_q$ and has order $q^3-q$, the number of ordered triples of distinct points; hence the action is sharply $3$-transitive, and a nonidentity element fixes at most two points.
If $q$ is even, every element of $\mathbb F_q^\times$ is a square, so $\mathrm{PSL}(2,q)$, the group of M\"obius maps with $ad-bc$ a nonzero square, equals $\mathrm{PGL}(2,q)$; \citet[p.~3]{leemans2009pgl} record the isomorphism.

\label{ext:matroid}
Let $E$ be a finite set and let $\operatorname{cl}$ be an operator on the subsets of $E$ such that, for all $A,B\subseteq E$ and $x,y\in E$:
(CL1) $A\subseteq\operatorname{cl}(A)$;
(CL2) if $A\subseteq B$, then $\operatorname{cl}(A)\subseteq\operatorname{cl}(B)$;
(CL3) $\operatorname{cl}(\operatorname{cl}(A))=\operatorname{cl}(A)$;
(CL4) if $y\in\operatorname{cl}(A\cup\{x\})\setminus\operatorname{cl}(A)$, then $x\in\operatorname{cl}(A\cup\{y\})$.
Then the sets $I\subseteq E$ with $x\notin\operatorname{cl}(I\setminus\{x\})$ for every $x\in I$ are the independent sets of a matroid on $E$ whose closure operator is $\operatorname{cl}$.

\label{ext:bcdmy}
\begin{enumerate}[label=(\alph*)]
\item \textup{(Theorem~A.)} A class $\mathcal{H}\subseteq Y^X$ is PAC learnable if and only if $\operatorname{DS}(\mathcal{H})<\infty$.
\item Let $F$ be a finite group and $H_1,\dots,H_d\le F$ subgroups with $\big(\bigcap_{j\neq i}H_j\big)\setminus H_i\neq\emptyset$ for every $i$. Then the coset complex $\{(gH_1,\dots,gH_d) : g\in F\}$ is a $d$-dimensional pseudo-cube.
\end{enumerate}

\label{ext:darnstadt}
Let $\mathcal K$ be a family of subsets of a nonempty set $Z$ that is closed under intersections of arbitrary subfamilies and has VC dimension $d$.
For every target $K^\star\in\mathcal K$, every distribution on $Z$ and every $m>0$, with probability at least $1-\delta$ over $m$ i.i.d.\ examples labeled by $K^\star$, the closure hypothesis (the intersection of all members of $\mathcal K$ consistent with the sample, which is the smallest member of $\mathcal K$ that contains the positive examples) has error at most $\frac{48}{m}\big(d\log880+\log(24/\delta)\big)$.

\label{lem:mingen}
Let $G$ be a finite group with a chief series $1=G_0<G_1<\dots<G_r=G$ whose factors are all abelian, and let $c$ be its number of complemented factors.
Then every minimal generating set $T$ of $G$ has $|T|\le c$.

\label{lem:unitcells}
Let $(V_i,k_i)_{i\le t}$ be $2$-full, and pick $g_i\in C_{e_i}$ for each~$i$.
Then $k_iV_i=g_iV_i$, $g_i\notin V_i$ and $\langle g_j:j\neq i\rangle\le V_i$; in particular $\{g_1,\dots,g_t\}$ is an independent set of size~$t$.

\label{lem:young}
Let $[n]=A\sqcup B$ with $|A|>|B|\ge1$, and let $V\le S_n$ contain $\operatorname{Sym}(A)\times\operatorname{Sym}(B)$.
If $V\neq S_n$, then $VA=A$.
